  L.slice(pg.from,pg.to).map(c=>{const p=pn(c.n);let over=false;for(let d=c.a;d<=c.b&&!over;d=addD(d,1))over=checkDay(d).some(v=>v.s==='Pusmantap'||v.s===p.t);return '<tr><td>'+nkc(c.n)+' <span class="t-xs t-muted">'+H(tshort(p.t)||'—')+'</span></td><td class="t-sm">'+H(c.jn)+(c.khusus?' <span class="t-chip t-gr">status khusus</span>':'')+'</td><td class="t-sm">'+fmtS(c.a)+(c.a!==c.b?'–'+fmtS(c.b):'')+' '+(over?'<span class="t-chip t-b-c" title="Ada hari yang melewati batas">'+ic('alert','s')+'</span>':'')+'</td><td class="t-sm">'+wdN(c)+'</td><td style="text-align:right">'+(canEdit()?'<button type="button" class="t-btn t-sm" data-tcf="'+H(c.n)+'|'+c.ci+'">'+ic('edit','s')+'Ubah</button>':'')+'</td></tr>'}).join('')+(L.length?'':'<tr><td colspan="5" class="t-empty">Belum ada rencana cuti</td></tr>')+'</tbody></table>';
