 const jt='<table class="t-tbl"><thead><tr><th>Jenis</th><th>Durasi standar</th><th>Pegawai</th><th></th></tr></thead><tbody><tr><td><b>Definitif (Pegawai Tetap)</b></td><td class="t-muted">tanpa batas</td><td>'+P.filter(p=>!p.tmp).length+'</td><td></td></tr>'+J.map((j,i)=>'<tr><td><b>'+H(j.n)+'</b> <span class="t-chip t-tmp">sementara</span></td><td><span class="t-fld"><input type="number" min="1" max="36" value="'+j.d+'" data-tjd="'+i+'" style="width:62px" '+(canEdit()?'':'disabled')+'> bulan</span></td><td>'+A.filter(p=>p.jen.toLowerCase()===j.n.toLowerCase()).length+'</td><td style="text-align:right">'+(canEdit()?'<button type="button" class="t-ibtn" style="display:inline-grid" data-tjdel="'+i+'" aria-label="Hapus">'+ic('x','s')+'</button>':'')+'</td></tr>').join('')+(canEdit()?'<tr><td><span class="t-fld"><input id="t2-jn-new" placeholder="Jenis lainnya, mis. Tenaga Ahli" style="width:100%"></span></td><td><span class="t-fld"><input id="t2-jd-new" type="number" min="1" max="36" value="6" style="width:62px"> bulan</span></td><td></td><td style="text-align:right"><button type="button" class="t-btn t-sm t-pri" data-tjadd>'+ic('plus','s')+'Tambah</button></td></tr>':'')+'</tbody></table>';
