/* ================= TAB PENDAMPINGAN UNIT ================= */
function unitList(){const k=kpCfg();return [...new Set([...UNITS_ALL(),...Object.keys(k.asg),...kpPeople().map(c=>c.unit).filter(Boolean)])]}
function uScore(u){const k=kpCfg(),d=(k.asg[u]||[]).map(n=>P.find(p=>p.n===n)).filter(Boolean),pm=d.filter(isPMO),cm=d.filter(isCMO),cs=kpPeople().filter(c=>c.unit===u),c={pmo:cs.filter(x=>(x.peran||[]).includes('pmo')),cmo:cs.filter(x=>(x.peran||[]).includes('cmo')),pb:cs.filter(x=>(x.peran||[]).includes('probis'))},miss=[];if(!pm.length)miss.push('PMO Kemenkeu');if(!cm.length)miss.push('CMO Kemenkeu');if(!c.pmo.length)miss.push('PMO Unit');if(!c.cmo.length)miss.push('CMO Unit');if(!c.pb.length)miss.push('Pemilik Probis');return {pm,cm,c,miss,sc:5-miss.length}}
const ringC=sc=>sc===5?'var(--t-o)':sc>=3?'#D99A00':'var(--t-c)',ring=sc=>'<span class="t-ring" style="background:conic-gradient('+ringC(sc)+' '+(sc*72)+'deg,#E9EDF4 0)" title="Kelengkapan '+sc+' dari 5"><span style="color:var(--t-navy)">'+sc+'/5</span></span>';
function vUnit(){const all=unitList().map(u=>Object.assign({u},uScore(u))),need=all.filter(x=>x.sc<5),okk=all.filter(x=>x.sc===5);
 const list=(ST.uf==='need'?need:ST.uf==='ok'?okk:all).filter(x=>!ST.q||(x.u+' '+x.pm.concat(x.cm).map(p=>p.n+' '+nk(p)).join(' ')).toLowerCase().includes(ST.q.toLowerCase())).sort((a,b)=>a.sc-b.sc||a.u.localeCompare(b.u));
 const ch=p=>'<span class="t-nkc"><i style="background:'+SC[code(p,today())]+'"></i>'+H(nk(p))+'</span>';
 const card=x=>'<button type="button" class="t-uc" data-tunit="'+H(x.u)+'"><div class="t-top"><div><h4>'+H(x.u)+'</h4></div>'+ring(x.sc)+'</div><div class="t-lbl">PENDAMPING KEMENKEU</div><div class="t-prow"><span class="t-k" style="color:var(--t-navy2)">PMO</span>'+(x.pm.length?x.pm.map(ch).join(''):'<span class="t-warn">belum ada</span>')+'</div><div class="t-prow"><span class="t-k" style="color:var(--t-v)">CMO</span>'+(x.cm.length?x.cm.map(ch).join(''):'<span class="t-warn">belum ada</span>')+'</div><div class="t-lbl">KONTAK DI UNIT</div><div class="t-cnts"><span class="'+(x.c.pmo.length?'':'t-z')+'"><b>'+x.c.pmo.length+'</b>PMO Unit</span><span class="'+(x.c.cmo.length?'':'t-z')+'"><b>'+x.c.cmo.length+'</b>CMO Unit</span><span class="'+(x.c.pb.length?'':'t-z')+'"><b>'+x.c.pb.length+'</b>Pemilik Probis</span></div>'+(x.miss.length?'<div class="t-miss">'+x.miss.map(m=>'<span>'+ic('alert','s')+m+'</span>').join('')+'</div>':'<div class="t-okline">'+ic('check','s')+'Lengkap</div>')+'</button>';
 return '<div class="t-card"><div class="t-head">'+seg()+'</div><div class="t-toolrow"><div class="t-fchips" style="margin:0"><button type="button" data-tuf="all" class="'+(ST.uf==='all'?'t-on':'')+'">Semua unit '+all.length+'</button><button type="button" data-tuf="need" class="'+(ST.uf==='need'?'t-on':'')+'">Perlu dilengkapi '+need.length+'</button><button type="button" data-tuf="ok" class="'+(ST.uf==='ok'?'t-on':'')+'">Lengkap '+okk.length+'</button></div><div class="t-tools">'+srch('Cari unit atau nama…')+(canEdit()?'<button type="button" class="t-btn" data-act="kuBackup">'+ic('ul','s')+'Kontak dari Backup DCM</button>':'')+'</div></div><div class="t-ugrid">'+(list.map(card).join('')||'<div class="t-empty">Tidak ditemukan</div>')+'</div></div>'}

