const useg=()=>'<div class="t-seg"><button type="button" data-tv="pend" class="'+(ST.v!=='tim'?'t-on':'')+'">'+ic('shield','s')+'Pendamping Kemenkeu</button><button type="button" data-tv="tim" class="'+(ST.v==='tim'?'t-on':'')+'">'+ic('users','s')+'Tim Unit Saya</button></div>';
const noPub='<div class="t-empty" style="padding:30px">Data pendamping Kemenkeu belum diterbitkan. Data otomatis tersedia setelah PMO/CMO Kemenkeu membuka menu Tim Pusmantap.</div>';
function vPendamping(){const u=(ME&&ME.unit)||'',x=PUB&&PUB.units&&PUB.units[u],d=x?x.pend.map(n=>P.find(p=>p.n===n)).filter(Boolean):[];
 return '<div class="t-card"><div class="t-head">'+useg()+'</div><div class="t-uhero">'+avX(u||'?','#0E2A5C','md')+'<div><h3>Pendamping dari Kemenkeu untuk '+H(u)+'</h3><p>PMO & CMO Kemenkeu (Pusmantap) yang mendampingi unit Anda. Klik kartu untuk kontak dan agenda.</p></div></div>'+(PUB?'<div class="t-pcards">'+(d.map(persCard).join('')||'<div class="t-empty">Belum ada pendamping yang ditetapkan untuk '+H(u)+'.</div>')+'</div>':noPub)+'<div class="t-lock">'+ic('lock')+'<span>Unit hanya melihat nama, jabatan, tim, status hari ini (tanpa alasan rinci), WhatsApp dan email kantor. NIP, pangkat, email pribadi, keahlian, dan rencana cuti tidak ditampilkan.</span></div></div>'}
