 if((el=g('[data-tacc]'))&&!g('button:not(.ttlbtn):not(.acc),select,input,label')){const c=cols(),k=el.dataset.tacc,i=c.indexOf(k);i>=0?c.splice(i,1):c.push(k);lsSet('col',c);rr();return}
 if((el=g('[data-taccall]'))){lsSet('col',el.dataset.taccall==='1'?hl().slice():[]);rr();return}
