 if((el=g('[data-tcv]'))){ST.calView=el.dataset.tcv;lsSet('calView',ST.calView);rr();return}
 if((el=g('[data-tmon]'))){ST.calM+= +el.dataset.tmon;if(ST.calM>11){ST.calM=0;ST.calY++}if(ST.calM<0){ST.calM=11;ST.calY--}const ov=overDays(ST.calY,ST.calM);ST.calSel=ov[0]||(today().slice(0,7)===iso(new Date(ST.calY,ST.calM,1)).slice(0,7)?today():iso(new Date(ST.calY,ST.calM,1)));rr();return}
