 if((el=g('[data-text]'))){const n=el.dataset.text,p=pn(n),j=C().jenis.find(x=>x.n.toLowerCase()===String(p.jen).toLowerCase())||{d:3};savePic(n,r=>{const base=r.penSelesai&&r.penSelesai>=today()?r.penSelesai:today();const d=D(base);d.setMonth(d.getMonth()+j.d);r.penSelesai=iso(d);if(!r.penMulai)r.penMulai=today()});toastT(nk(p)+' diperpanjang '+j.d+' bulan.');rr();return}
