function onPointerDown(e){const g=e.target.closest('#t2 [data-tgrip],#t2 [data-tblk],#t2 [data-trsz]');if(!g)return;
 if(g.matches('[data-trsz]')){e.preventDefault();e.stopPropagation();const k=g.dataset.trsz,bk=g.closest('.t-blk'),grid=document.getElementById('t2-lgrid'),gr=grid.getBoundingClientRect(),colW=(gr.width-32-11*12)/12,left=bk.getBoundingClientRect().left;g.setPointerCapture(e.pointerId);grid.classList.add('t-rs');let cur=size(k);
  g.onpointermove=ev=>{const raw=(ev.clientX-left+12)/(colW+12),sp=SPANS.reduce((a,b)=>Math.abs(b-raw)<Math.abs(a-raw)?b:a);if(sp!==cur){cur=sp;bk.style.gridColumn='span '+sp;const s=bk.querySelector('.t-spn');if(s)s.textContent=SPL[sp]}};
  g.onpointerup=g.onpointercancel=()=>{g.onpointermove=null;const z=sizes();z[k]=cur;lsSet('sz',z);toastT(WDEF[k].t+': lebar '+SPL[cur]);rr()};return}
 if(g.matches('[data-tblk]')&&e.target.closest('[data-nodrag]'))return;
 e.preventDefault();const blk=g.matches('[data-tblk]'),el=blk?g:g.closest('.t-w'),grid=document.getElementById(blk?'t2-lgrid':'t2-wgrid');if(!el||!grid)return;
 DR={k:blk?g.dataset.tblk:g.dataset.tgrip,x0:e.clientX,y0:e.clientY,t:null,after:false,slot:null};g.setPointerCapture(e.pointerId);el.classList.add('t-dragging');grid.classList.add('t-dnd');
 g.onpointermove=ev=>{if(!DR)return;el.style.transform='translate('+(ev.clientX-DR.x0)+'px,'+(ev.clientY-DR.y0)+'px) scale(1.01)';const at=document.elementFromPoint(ev.clientX,ev.clientY);document.querySelectorAll('#t2 .t-drop-b,#t2 .t-drop-a,#t2 .t-drop').forEach(x=>x.classList.remove('t-drop-b','t-drop-a','t-drop'));DR.t=null;DR.slot=null;
  const sl=at&&at.closest('#t2 .t-eslot,#t2 .t-slot');if(sl&&blk&&sl.dataset.teslot){DR.slot=sl.dataset.teslot;sl.classList.add('t-drop');return}
  const tg=at&&at.closest(blk?'#t2 .t-blk[data-tblk]':'#t2 .t-w[data-tw]');if(tg&&tg!==el){const r=tg.getBoundingClientRect(),after=ev.clientX>r.left+r.width/2;DR.t=blk?tg.dataset.tblk:tg.dataset.tw;DR.after=after;tg.classList.add(after?'t-drop-a':'t-drop-b')}if(ev.clientY<70)window.scrollBy(0,-14);if(ev.clientY>innerHeight-60)window.scrollBy(0,14)};
 g.onpointerup=g.onpointercancel=()=>{const d=DR;DR=null;g.onpointermove=null;if(d&&d.slot===d.k)d.slot=null;if(d&&(d.t||d.slot)){const ws=hl();ws.splice(ws.indexOf(d.k),1);if(d.slot){const i=ws.indexOf(d.slot);ws.splice(i<0?ws.length:i+1,0,d.k)}else ws.splice(ws.indexOf(d.t)+(d.after?1:0),0,d.k);hlSet(ws);toastT(WDEF[d.k].t+' dipindah.')}rr()}}
function onDragStart(e){const c=e.target.closest&&e.target.closest('#t2 .t-p[draggable=true]');if(!c)return;e.dataTransfer.setData('text/plain',c.dataset.tn+'\u0001'+(c.dataset.tfrom||''));e.dataTransfer.effectAllowed='move'}
function onDragOver(e){const c=e.target.closest&&e.target.closest('#t2 .t-col[data-tteam]');if(!c||!canEdit())return;e.preventDefault();document.querySelectorAll('#t2 .t-col.t-over').forEach(x=>x!==c&&x.classList.remove('t-over'));c.classList.add('t-over')}
