/* ---------- impor Resource Tim CM (Backup All Dashboard CM) ---------- */
function mapRes(r){const pen=String(r.penugasan||''),jenisS=/re-?entry/i.test(pen)?'Re-Entry':/second/i.test(pen)?'Secondment':/magang/i.test(pen)?(/kemnaker/i.test(pen)?'Magang Kemnaker':'Magang Kemenkeu'):'';
 return {n:String(r.nama||'').trim(),nip:r.nip||'',jab:r.jabatan||'',pang:[r.pangkat,r.golongan].filter(Boolean).join(' / '),unitAsal:r.unit||'',emailK:r.emailKemenkeu||'',emailP:r.emailPribadi||'',hp:r.noHp||'',peran:r.peran||'',rangkap:r.rangkap||'',penugasan:pen,penMulai:r.penugasanMulai||'',penSelesai:r.penugasanSelesai||'',jenis:jenisS?'Sementara':'Definitif',jenisSementara:jenisS,keahlian:(Array.isArray(r.keahlian)?r.keahlian:String(r.keahlian||'').split(',')).map(s=>String(s).trim()).filter(Boolean).join(', '),wfhDays:Array.isArray(r.wfhDays)?r.wfhDays.map(Number):[],status:['WFO','WFH','Cuti','Nonaktif'].includes(r.status)?r.status:'WFO',statusKerja:['WFO','WFH','Cuti','Nonaktif'].includes(r.status)?r.status:'WFO',statusMulai:r.statusMulai||'',statusSelesai:r.statusSelesai||'',jenisCuti:r.jenisCuti||'',catatanStatus:r.catatanStatus||'',foto:r.foto||'',cuti:(Array.isArray(r.rencanaCuti)?r.rencanaCuti:[]).filter(c=>c&&c.mulai).map(c=>({mulai:c.mulai,selesai:c.selesai||c.mulai,jenis:c.jenis||'Cuti Tahunan',catatan:c.catatan||''}))}}
function impDcm(){if(!canEdit())return;const ov=modal('Impor Resource Tim CM dari Dashboard CM','<p class="t-s" style="margin:0 0 8px">Di Dashboard CM klik <b>Backup All</b>, lalu pilih file <code>.json</code> yang terunduh. Profil, foto, jadwal WFH, status, dan rencana cuti disalin ke Tim Pusmantap. Pegawai yang sudah ada diperbarui (kolom kosong tidak menimpa). Pegawai baru otomatis masuk <b>Tim CM</b> (bisa dipindah).</p><input type="file" id="t2-dcm-f" accept=".json,application/json"><div id="t2-dcm-r" class="t-s" style="margin-top:8px"></div>','Impor',ov=>{const L=ov._res;if(!L||!L.length){toastT('Pilih file backup yang berisi resources.');return false}
  const M=actMaster(),k=kpCfg();let add=0,upd=0;const cm=k.tims.find(t=>/(^|\s)CM(\s|$)/i.test(t))||k.tims[k.tims.length-1];
  L.map(mapRes).filter(o=>o.n).forEach(o=>{const ex=M.pic.find(x=>x.n.toLowerCase()===o.n.toLowerCase()||(o.nip&&x.nip===o.nip));if(ex){Object.keys(o).forEach(key=>{const v=o[key];if(key==='n')return;if(Array.isArray(v)?v.length:v)ex[key]=v});upd++;if(!k.pt[ex.n]&&cm)k.pt[ex.n]=cm}else{M.pic.push(o);add++;if(cm)k.pt[o.n]=cm}});
  actMasterSave(M);try{log('Impor Resource Tim CM (Dashboard CM)',add+' baru, '+upd+' diperbarui')}catch(e){}toastT(add+' pegawai baru, '+upd+' diperbarui.');rr()},{size:'md'});
 ov.querySelector('#t2-dcm-f').onchange=async e=>{const f=e.target.files[0],out=ov.querySelector('#t2-dcm-r');if(!f)return;try{const j=JSON.parse(await f.text());const L=Array.isArray(j.resources)?j.resources:Array.isArray(j)?j:[];if(!L.length)throw new Error('File tidak berisi data resources (Resource Tim CM).');ov._res=L;out.innerHTML='Terbaca <b>'+L.length+'</b> pegawai: '+L.slice(0,8).map(r=>H(r.nama)).join(', ')+(L.length>8?', …':'')}catch(er){ov._res=null;out.innerHTML='<span style="color:var(--bad)">'+H(er.message)+'</span>'}}}
function impPengelola(){if(!canEdit())return;let x=null;try{x=S.modMeta.__PENGELOLA_TRANSFORMASI__}catch(e){}if(!x||!x.people||!x.people.length){toastT('Data menu Pengelola kosong.');return}
 confirmDel('data menu Pengelola lama ('+x.people.length+' orang)',()=>{const M=actMaster(),k=kpCfg();k.ptx=k.ptx||{};let add=0,upd=0;
  x.people.forEach(o=>{const n=String(o.name||'').trim();if(!n)return;let ex=M.pic.find(p=>p.n.toLowerCase()===n.toLowerCase());const v={n,nip:o.nip||'',jab:o.position||'',unitAsal:o.unit||'',emailK:o.email||'',hp:o.phone||'',foto:o.photo||'',pang:o.pangkat||'',keahlian:Array.isArray(o.skills)?o.skills.join(', '):(o.skills||''),wfhDays:Array.isArray(o.wfh)?o.wfh.map(d=>(+d+1)%7):[],jenis:/magang|re-?entry|second/i.test(o.type||'')?'Sementara':'Definitif',jenisSementara:/magang/i.test(o.type||'')?'Magang Kemnaker':/re-?entry/i.test(o.type||'')?'Re-Entry':/second/i.test(o.type||'')?'Secondment':''};
   if(ex){Object.keys(v).forEach(key=>{if(key!=='n'&&v[key]&&!(Array.isArray(v[key])&&!v[key].length)&&!ex[key])ex[key]=v[key]});upd++}else{M.pic.push(Object.assign({status:'WFO',cuti:[]},v));add++}
   const asg=(x.assignments||[]).filter(a=>a.personId===o.id);asg.forEach(a=>{const tm=k.tims.find(t=>tshort(t).toUpperCase()===String(a.program||'').toUpperCase());if(!tm)return;if(!k.pt[n])k.pt[n]=tm;else if(k.pt[n]!==tm&&!(k.ptx[n]||[]).includes(tm))k.ptx[n]=(k.ptx[n]||[]).concat(tm);if(a.unit){k.asg[a.unit]=k.asg[a.unit]||[];if(!k.asg[a.unit].includes(n))k.asg[a.unit].push(n)}})});
  actMasterSave(M);try{log('Impor data menu Pengelola',add+' baru, '+upd+' diperbarui')}catch(e){}toastT(add+' pegawai baru, '+upd+' dilengkapi dari menu Pengelola.');rr()},{delHead:'Impor data menu Pengelola?',delMsg:w=>'<p style="margin:0">Salin '+H(w)+' ke Tim Pusmantap: profil yang sudah ada hanya dilengkapi (tidak ditimpa), penugasan program menjadi tim, unit penanggung jawab menjadi unit dampingan.</p>',okLabel:'Impor'})}

